# Inputs are constructed within the stated limits and preserve problem-specific invariants.
import random


def generate(seed=0):
    r = random.Random(seed)
    vals = {"abcde", "aaaaaaaaaaaaaabb"}
    while len(vals) < 600:
        vals.add("".join(r.choice("abcde") for _ in range(r.randint(1, 200))))
    calls = [f"candidate(word={s!r})" for s in vals]
    calls.append(
        "candidate(word='')"
    )
    assert 500 <= len(calls) <= 999
    assert len(calls) == len(set(calls))
    return calls
